package com.iceymod.screen;

import com.iceymod.IceyMod;
import com.iceymod.compat.Gfx;
import net.minecraft.resources.Identifier;

import java.util.HashMap;
import java.util.Map;

/**
 * The hand-drawn 12x12 pixel icons of the card menu, one per module.
 * GENERATED by mod/tools/gen_mod_icons.py together with mod_icons.png:
 * edit the drawings there, not this file.
 */
final class ModIcons {
    private ModIcons() {}

    static final int SIZE = 12;
    private static final int COLS = 12, ROWS = 7;
    private static final Identifier TEX = Identifier.fromNamespaceAndPath(IceyMod.MOD_ID, "textures/gui/mod_icons.png");
    private static final String[] IDS = { "fps", "ping", "coords", "cps", "keystrokes", "armor", "hitboxes", "itemglow", "direction", "daycounter", "server", "potions", "memory", "saturation", "combo", "time", "entitycount", "weather", "lastdamage", "cooldown", "perspective", "nethercoords", "velocity", "obsidian", "automaceswap", "macedamage", "fpsboost_clouds", "air", "biomelocator", "fullbright", "toolwarn", "net_ipv4", "ylevel", "itemcd", "blocksmined", "arrows", "nearestplayer", "blockunder", "fpsboost_particles", "elytra", "pearls", "nofovchange", "mobkills", "deaths", "gapples", "zoom", "nohurtcam", "freecam", "bedcoords", "biome", "hostilecount", "net_dnscache", "structurelocator", "safewalk", "pitchyaw", "tps", "nobob", "worldtime", "session", "killstreak", "crystaltracker", "totems", "fpsboost_shadows", "totempops", "net_nodelay", "autorespawn", "falldist", "distwalked", "lookat", "autosprint", "freelook", "crosshair", "invslots", "net_buffer", "crystalcps", "antiafk", "chunk", "autototem", "offhand", "fpsboost_graphics", "hotbartext", "nearesthostile", "waypoints" };
    private static final Map<String, Integer> INDEX = new HashMap<>();
    static { for (int i = 0; i < IDS.length; i++) INDEX.put(IDS[i], i); }

    static boolean has(String id) { return INDEX.containsKey(id); }

    /** Draws the icon of {@code id} at 1:1 (12x12); scale with the pose. False when the module has none. */
    static boolean draw(Gfx g, String id, int x, int y, boolean bright) {
        Integer n = INDEX.get(id);
        if (n == null) return false;
        g.blit(TEX, x, y, (n % COLS) * SIZE, (n / COLS + (bright ? 0 : ROWS)) * SIZE, SIZE, SIZE, COLS * SIZE, ROWS * SIZE * 2);
        return true;
    }
}
